<script setup lang="ts">
import { computed, ref } from 'vue'
import { Check, Info, Plus, Search, X } from '@lucide/vue'
import { eventRates, type EventRateType } from '@/features/events/stores/eventRates'

const types: EventRateType[] = ['Accommodation', 'Conference', 'Lunch', 'Dinner', 'Other']
const search = ref('')
const typeFilter = ref('All types')
const statusFilter = ref('All statuses')
const clientFilter = ref('Guest or company')
const dateFilter = ref('All dates')
const showForm = ref(false)
const notice = ref('')
const clients = ['All clients', 'Ecobank Ghana', 'Hotel HR', 'North Star Ltd.', 'Asteria Group']
const form = ref({ name: '', types: [] as EventRateType[], amounts: { Accommodation: '', Conference: '', Lunch: '', Dinner: '', Other: '' } as Record<EventRateType, string>, alwaysEffective: false, from: '2026-01-01', to: '2026-12-31', clientSpecific: false, client: '', active: true })
const filteredRates = computed(() => eventRates.value.filter((rate) => {
  const query = search.value.trim().toLowerCase()
  const matchesSearch = !query || [rate.packageName, rate.type, rate.client].some((value) => value.toLowerCase().includes(query))
  const matchesType = typeFilter.value === 'All types' || rate.type === typeFilter.value
  const matchesStatus = statusFilter.value === 'All statuses' || (statusFilter.value === 'Effective' ? rate.active : !rate.active)
  const matchesClient = clientFilter.value === 'Guest or company' || rate.client === clientFilter.value
  const today = new Date().toISOString().slice(0, 10)
  const effective = rate.alwaysEffective || (rate.from <= today && rate.to >= today)
  const matchesDate = dateFilter.value === 'All dates' || (dateFilter.value === 'Effective now' ? effective : !effective)
  return matchesSearch && matchesType && matchesStatus && matchesClient && matchesDate
}))
function money(amount: number) { return `₱${amount.toLocaleString('en-PH', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}` }
function effective(rate: typeof eventRates.value[number]) { if (!rate.active) return 'Inactive'; const today = new Date().toISOString().slice(0, 10); return rate.alwaysEffective || (rate.from <= today && rate.to >= today) ? 'Effective' : 'Scheduled' }
function toggleType(type: EventRateType) { form.value.types = form.value.types.includes(type) ? form.value.types.filter((value) => value !== type) : [...form.value.types, type] }
function resetForm() { form.value = { name: '', types: [], amounts: { Accommodation: '', Conference: '', Lunch: '', Dinner: '', Other: '' }, alwaysEffective: false, from: '2026-01-01', to: '2026-12-31', clientSpecific: false, client: '', active: true } }
function saveRate() {
  if (!form.value.types.length || (form.value.clientSpecific && !form.value.client) || form.value.types.some((type) => !Number.isFinite(Number(form.value.amounts[type])) || Number(form.value.amounts[type]) <= 0) || (!form.value.alwaysEffective && (!form.value.from || !form.value.to || form.value.to < form.value.from))) return
  const packageName = form.value.name.trim() || 'Event rate package'
  for (const type of form.value.types) {
    eventRates.value.push({ id: `RATE-${Date.now()}-${type}`, packageName, type, client: form.value.clientSpecific ? form.value.client : 'All clients', amount: Number(form.value.amounts[type]), from: form.value.alwaysEffective ? '' : form.value.from, to: form.value.alwaysEffective ? '' : form.value.to, active: form.value.active, alwaysEffective: form.value.alwaysEffective })
  }
  showForm.value = false
  resetForm()
  notice.value = 'Rate package saved.'
  window.setTimeout(() => { notice.value = '' }, 3000)
}
</script>

<template>
  <section class="space-y-4">
    <header class="flex flex-wrap items-end justify-between gap-3"><div><p class="eyebrow">Events &amp; Conferences</p><h1 class="mt-1 font-serif text-[29px] font-medium tracking-[-0.035em] text-[#30243e]">Guest Rates</h1><p class="mt-1 text-[10px] text-[#7d7583]">Set effective event prices for accommodation, conference, lunch, dinner, and other services.</p></div><button class="arrival-action-primary" @click="showForm = true"><Plus :size="13" /> New rate</button></header>
    <p v-if="notice" class="rounded-md border border-[#cfe5d8] bg-[#f0f8f3] px-3 py-2 text-[9px] text-[#44805b]">{{ notice }}</p>
    <section class="overflow-hidden rounded-lg border border-[#e7e2e9] bg-[#fffdfb]"><div class="flex flex-wrap gap-2 border-b border-[#eeeaf0] p-3"><label class="client-search min-w-[180px] flex-1"><Search :size="12" /><span class="sr-only">Search rates</span><input v-model="search" placeholder="Search rates by name, type, client..." /></label><select v-model="typeFilter" class="report-select"><option>All types</option><option v-for="type in types" :key="type">{{ type }}</option></select><select v-model="statusFilter" class="report-select"><option>All statuses</option><option>Effective</option><option>Inactive</option></select><select v-model="clientFilter" class="report-select"><option>Guest or company</option><option v-for="client in clients" :key="client">{{ client }}</option></select><select v-model="dateFilter" class="report-select"><option>All dates</option><option>Effective now</option><option>Not effective</option></select></div><div class="flex items-center justify-between border-b border-[#eeeaf0] px-4 py-2"><h2 class="text-[11px] font-semibold text-[#44394c]">Rates</h2><span class="text-[8px] text-[#8b8490]">{{ filteredRates.length }} rates</span></div><div class="overflow-x-auto"><table class="w-full min-w-[780px] border-collapse text-left"><thead class="bg-[#faf9fb] text-[8px] uppercase tracking-[0.06em] text-[#817987]"><tr><th class="px-4 py-3">Client</th><th class="px-4 py-3">Rate</th><th class="px-4 py-3">Type</th><th class="px-4 py-3 text-right">Amount</th><th class="px-4 py-3">Period</th><th class="px-4 py-3">Status</th><th class="px-4 py-3"></th></tr></thead><tbody><tr v-for="rate in filteredRates" :key="rate.id" class="border-t border-[#f0edf1] text-[9px] text-[#59636c]"><td class="px-4 py-3">{{ rate.client }}</td><td class="px-4 py-3"><strong class="block font-medium text-[#35414a]">{{ rate.packageName }}</strong><span class="text-[8px] text-[#8b949a]">1 rate · {{ rate.type }} rate for event bookings</span></td><td class="px-4 py-3"><span class="rounded-full px-2 py-1 text-[8px]" :class="rate.type === 'Accommodation' ? 'bg-[#e6f1fb] text-[#4e7298]' : rate.type === 'Conference' ? 'bg-[#f1eafb] text-[#735599]' : rate.type === 'Lunch' ? 'bg-[#fff3dc] text-[#916b35]' : rate.type === 'Dinner' ? 'bg-[#e6f6ee] text-[#39764f]' : 'bg-[#f2f2f2] text-[#68727a]'">{{ rate.type }}</span></td><td class="px-4 py-3 text-right">{{ money(rate.amount) }}</td><td class="whitespace-nowrap px-4 py-3"><span v-if="rate.alwaysEffective">Always effective</span><span v-else>{{ new Date(`${rate.from}T12:00:00`).toLocaleDateString('en-PH', { day: 'numeric', month: 'short', year: 'numeric' }) }} – {{ new Date(`${rate.to}T12:00:00`).toLocaleDateString('en-PH', { day: 'numeric', month: 'short', year: 'numeric' }) }}</span></td><td class="px-4 py-3"><span class="rounded-full px-2 py-1 text-[8px]" :class="effective(rate) === 'Effective' ? 'bg-[#e5f6ed] text-[#39764f]' : effective(rate) === 'Inactive' ? 'bg-[#f1f1f2] text-[#737980]' : 'bg-[#fff2df] text-[#916b35]'">{{ effective(rate) }}</span></td><td class="px-4 py-3 text-right"><button class="text-[8px] text-[#704b99] hover:underline" @click="rate.active = !rate.active">{{ rate.active ? 'Deactivate' : 'Activate' }}</button></td></tr><tr v-if="filteredRates.length === 0"><td colspan="7" class="py-12 text-center text-[10px] text-[#8b8490]">No rates match the selected filters.</td></tr></tbody></table></div></section>
    <div v-if="showForm" class="modal-backdrop" @click.self="showForm = false"><section class="modal-card max-h-[92vh] max-w-[570px] overflow-y-auto text-left" role="dialog" aria-modal="true" aria-labelledby="new-rate-title"><header class="flex items-start justify-between"><div><p class="eyebrow">Events &amp; Conferences · pricing</p><h2 id="new-rate-title" class="mt-1 font-serif text-[21px] text-[#30243e]">New rate package</h2></div><button aria-label="Close rate form" @click="showForm = false"><X :size="15" /></button></header><label class="form-label mt-4 block">Rate name (optional)<input v-model="form.name" class="form-input mt-1" placeholder="e.g. Ecobank agreed conference rate" /></label><fieldset class="mt-4 rounded-md border border-[#e4e0e7] p-3"><legend class="px-1 text-[9px] font-medium text-[#59636c]">Select rate types <span class="text-[#a25454]">*</span></legend><div class="grid gap-2 sm:grid-cols-2"><label v-for="type in types" :key="type" class="flex items-center gap-2 rounded-md bg-[#faf9fb] px-3 py-2 text-[9px] text-[#46515a]"><input type="checkbox" class="accent-[#69489a]" :checked="form.types.includes(type)" @change="toggleType(type)" />{{ type }}</label></div></fieldset><div v-if="form.types.length" class="mt-3 grid gap-2 sm:grid-cols-2"><label v-for="type in form.types" :key="type" class="form-label">{{ type }} rate (₱)<input v-model="form.amounts[type]" class="form-input mt-1" type="number" min="0.01" step="0.01" placeholder="0.00" /></label></div><section class="mt-4 rounded-md border border-[#eeeaf0] p-3"><h3 class="text-[9px] font-semibold text-[#493d50]">Effective period <Info :size="10" class="ml-1 inline text-[#8b8490]" /></h3><label class="mt-2 flex items-center gap-2 text-[9px] text-[#59636c]"><input v-model="form.alwaysEffective" type="checkbox" class="accent-[#69489a]" />Always effective (all year)</label><div v-if="!form.alwaysEffective" class="mt-3 grid grid-cols-2 gap-2"><label class="form-label">Effective from <input v-model="form.from" class="form-input mt-1" type="date" /></label><label class="form-label">Effective to <input v-model="form.to" class="form-input mt-1" type="date" :min="form.from" /></label></div></section><section class="mt-3 rounded-md bg-[#faf9fb] p-3"><label class="flex items-center gap-2 text-[9px] text-[#59636c]"><input v-model="form.clientSpecific" type="checkbox" class="accent-[#69489a]" />Client-specific rate</label><select v-if="form.clientSpecific" v-model="form.client" class="form-input mt-2"><option value="">Choose client or company</option><option v-for="client in clients.slice(1)" :key="client">{{ client }}</option></select><label class="mt-3 flex items-center gap-2 text-[9px] text-[#59636c]"><input v-model="form.active" type="checkbox" class="accent-[#1474e8]" />Active</label></section><footer class="mt-5 flex justify-end gap-2"><button class="secondary-button" @click="showForm = false">Cancel</button><button class="arrival-action-primary" :disabled="!form.types.length || (form.clientSpecific && !form.client) || form.types.some((type) => !form.amounts[type] || Number(form.amounts[type]) <= 0) || (!form.alwaysEffective && (!form.from || !form.to || form.to < form.from))" @click="saveRate"><Check :size="12" /> Save rate package</button></footer></section></div>
  </section>
</template>
